const paths={
 tooth:'M7 3C2 3 2 8 4 12c1 3 1 9 4 9 2 0 1-7 4-7s2 7 4 7c3 0 3-6 4-9 2-4 2-9-3-9-2 0-3 1-5 1S9 3 7 3Z',
 grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',calendar:'M4 5h16v16H4z M16 3v4 M8 3v4 M4 10h16 M8 14h2 M14 14h2 M8 17h2',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M16 3a4 4 0 0 1 0 8 M22 21v-2a4 4 0 0 0-3-3.87 M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',clock:'M12 8v4l3 2 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',check:'m7 12 3 3 7-7 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',x:'m8 8 8 8 M16 8l-8 8 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',close:'m6 6 12 12 M18 6 6 18',plus:'M12 5v14 M5 12h14',search:'m21 21-5-5 M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',chevron:'m9 5 7 7-7 7',left:'m15 5-7 7 7 7',down:'m6 9 6 6 6-6',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9 M10 21h4',settings:'M12 8a4 4 0 1 1 0 8 4 4 0 0 1 0-8 M9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1Z',logout:'M10 4H4v16h6 M8 12h13 M17 8l4 4-4 4',history:'M3 11a9 9 0 1 1 2 7 M3 4v7h7 M12 7v5l4 2',repeat:'m17 2 4 4-4 4 M3 11V8a2 2 0 0 1 2-2h16 M7 22l-4-4 4-4 M21 13v3a2 2 0 0 1-2 2H3',shield:'m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6z m-4 9 3 3 5-6',arrow:'M4 12h16 m-5-5 5 5-5 5',more:'M5 12h.01 M12 12h.01 M19 12h.01',menu:'M3 6h18 M3 12h18 M3 18h18',spark:'m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5Z',mail:'M3 5h18v14H3z m0 0 9 7 9-7',filter:'M4 6h16 M7 12h10 M10 18h4',file:'M6 3h9l4 4v14H6z M14 3v5h5 M9 12h7 M9 16h7'};
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.calendar}"/></svg>`;
paths.eye='M2 12s3.5-7 10-7 10 7 10 7-3.5 7-10 7S2 12 2 12Z M15 12a3 3 0 1 1-6 0 3 3 0 0 1 6 0';
paths.eyeOff='m3 3 18 18 M10.6 5.1A12 12 0 0 1 12 5c6.5 0 10 7 10 7a18 18 0 0 1-3 3.8 M6.2 6.2A20 20 0 0 0 2 12s3.5 7 10 7a12 12 0 0 0 5.8-1.5 M10 10a3 3 0 0 0 4 4';
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const $=(s,root=document)=>root.querySelector(s);
const app=$('#app');
const state={user:null,data:null,view:'dashboard',tab:'All appointments',search:'',filter:'All services',page:1,calendar:new Date(new Date().getFullYear(),new Date().getMonth(),1),selectedDate:localDate(),week:0,notifications:false,accountMenu:false};
function localDate(date=new Date()){return `${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`;}
const dateFormat=(date,options={month:'short',day:'numeric',year:'numeric'})=>new Date(date+'T12:00:00').toLocaleDateString('en-US',options);
const timeFormat=t=>{const [h,m]=t.split(':').map(Number);return `${h%12||12}:${String(m).padStart(2,'0')} ${h<12?'AM':'PM'}`;};
const money=v=>'₱'+Number(v).toLocaleString('en-PH');
const initials=name=>name.split(' ').filter(Boolean).map(n=>n[0]).slice(0,2).join('');
const statusBadge=s=>`<span class="badge-status ${s.toLowerCase()}">${esc(s)}</span>`;
const person=(name,email='',id=0)=>`<div class="person"><span class="avatar" style="background:${['#edf1fc','#f9eee8','#eef4e9','#f2ecfa','#e8f3f5','#fcf0f0'][id%6]};color:${['#899bc0','#c09d85','#8eaa81','#ad94c0','#83a6b0','#bc9292'][id%6]}">${esc(initials(name))}</span><div><strong>${esc(name)}</strong>${email?`<small>${esc(email)}</small>`:''}</div></div>`;
let toastTimer;
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4200);}
async function api(route,method='GET',body){const response=await fetch('/api'+route,{method,headers:{'Content-Type':'application/json'},body:body?JSON.stringify(body):undefined});const result=await response.json();if(!response.ok){if(response.status===401&&state.user){state.user=null;renderAuth();}throw new Error(result.error||'Something went wrong.');}return result;}
const isAdmin=()=>state.user?.role==='admin';
const navs=()=>isAdmin()?[['dashboard','grid','Overview'],['appointments','calendar','Appointments'],['patients','users','Patients'],['schedule','clock','Schedule'],['dentists','users','Dentists'],['followups','repeat','Follow-ups'],['accounts','shield','Account management']]:[['dashboard','grid','Overview'],['appointments','calendar','My appointments'],['services','tooth','Dental services'],['history','history','Appointment history'],['service-history','file','Service history'],['followups','repeat','Follow up appointments'],['dentists','users','Our dentists']];
const titles={accounts:'Account management','service-history':'Service history',dentists:'Our dentists',dashboard:'Overview',appointments:'Appointments',patients:'Patients',schedule:'Schedule',followups:'Follow-ups',services:'Dental services',history:'Appointment history',profile:'Account information'};
function brand(){return `<div class="brand"><div class="brand-mark">${icon('tooth')}</div><div><div class="brand-name">NB MAGBANUA</div><div class="brand-clinic">DENTAL CLINIC</div><small>CARE BEYOND THE SMILE</small></div></div>`;}
async function refresh(){state.data=await api('/data');state.user=state.data.user;render();}
function render(){
  const pending=state.data.appointments.filter(a=>a.status==='Pending').length;
  app.innerHTML=`<aside class="sidebar">${brand()}<div class="nav-label">${isAdmin()?'Workspace':'Patient portal'}</div><nav aria-label="Main navigation">${navs().map(([view,i,label])=>`<button class="nav-item ${state.view===view?'active':''}" data-nav="${view}" ${state.view===view?'aria-current="page"':''}>${icon(i)}${label}${view==='appointments'&&pending?`<span class="count">${pending}</span>`:''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="clinic-card"><strong><span class="dot"></span> A little care. A brighter smile.</strong><p>Mon–Sat &nbsp; 9:00 AM – 5:00 PM</p></div><div class="side-foot"><button class="nav-item ${state.view==='profile'?'active':''}" data-nav="profile">${icon('settings')}My profile</button><button class="nav-item" data-action="logout">${icon('logout')}Log out</button></div></div></aside>
  <header class="topbar"><div class="breadcrumb"><button class="icon-btn mobile-toggle" data-action="menu" aria-label="Open navigation">${icon('menu')}</button>${icon('grid')}<span>${isAdmin()?'Workspace':'Patient portal'}</span><span>/</span><span>${state.view==='followups'&&!isAdmin()?'Follow up appointments':titles[state.view]}</span></div><div class="top-actions"><div class="top-date">${icon('calendar')}${new Date().toLocaleDateString('en-US',{weekday:'short',month:'short',day:'numeric',year:'numeric'})}</div><button class="icon-btn" data-action="notifications" aria-label="Notifications" aria-expanded="${state.notifications}">${icon('bell')}${state.data.unread_count?`<span class="notification-count" aria-label="${state.data.unread_count} unread notifications">${state.data.unread_count}</span>`:''}</button><div class="account-control"><button class="top-profile" data-action="account-menu" id="account-menu-toggle" aria-label="Account menu" aria-haspopup="menu" aria-controls="account-dropdown" aria-expanded="${state.accountMenu}">${profileAvatar(state.user)}<div><div class="profile-name">${esc(state.user.name)}</div><div class="profile-role">${isAdmin()?'Clinic administrator':'Patient account'}</div></div>${icon('down')}</button>${accountDropdown()}</div></div></header>
  ${state.notifications?notificationsView():''}<main class="main">${pageContent()}<footer class="footer"><span>© ${new Date().getFullYear()} NB MAGBANUA DENTAL CLINIC. Care beyond the smile.</span><span>${icon('shield')} Your care, thoughtfully organized.</span></footer></main>`;
  bindEvents();
}
function profileAvatar(user){
  return `<span class="avatar profile-avatar">${user.photo_url?`<img src="${esc(user.photo_url)}" alt="${esc(user.name)} profile picture">`:esc(initials(user.name))}</span>`;
}
function bindProfilePhoto(){
  const input=$('#profile-photo-input');if(!input)return;
  const choose=$('#choose-profile-photo'),remove=$('#remove-profile-photo'),status=$('#profile-photo-status'),error=$('#photo-error');
  function updatePictures(user){
    state.user=user;state.data.user=user;
    $('#profile-picture-preview').innerHTML=profileAvatar(user);
    const header=$('.top-profile>.avatar'),menu=$('.account-dropdown-summary>.avatar');
    if(header)header.outerHTML=profileAvatar(user);if(menu)menu.outerHTML=profileAvatar(user);
    remove.hidden=!user.photo_url;
  }
  async function savePhoto(file){
    error.textContent='';
    if(file&&!['image/jpeg','image/png','image/webp'].includes(file.type)){error.textContent='Choose a JPG, PNG, or WebP image.';input.value='';return;}
    if(file&&file.size>2*1024*1024){error.textContent='Choose an image no larger than 2 MB.';input.value='';return;}
    choose.disabled=true;remove.disabled=true;status.textContent=file?'Uploading picture…':'Removing picture…';
    try{
      let result;
      if(file){
        const response=await fetch('/api/profile/photo',{method:'PUT',headers:{'Content-Type':file.type},body:file});
        result=await response.json();if(!response.ok)throw new Error(result.error||'The picture could not be uploaded.');
      }else result=await api('/profile/photo','DELETE',{});
      updatePictures(result.user);status.textContent=file?'Profile picture updated.':'Profile picture removed.';
      toast(status.textContent);
    }catch(e){error.textContent=e.message;status.textContent='';}
    finally{choose.disabled=false;remove.disabled=false;input.value='';}
  }
  choose.onclick=()=>input.click();
  input.onchange=()=>{if(input.files[0])savePhoto(input.files[0]);};
  remove.onclick=()=>savePhoto(null);
}
function accountDropdown(){
  return `<div class="account-dropdown" id="account-dropdown" ${state.accountMenu?'':'hidden'}><div class="account-dropdown-summary">${profileAvatar(state.user)}<div><strong>${esc(state.user.name)}</strong><small>${esc(state.user.email)}</small></div></div><div role="menu" aria-label="Account options"><button class="account-dropdown-item" role="menuitem" data-nav="profile">${icon('settings')}<span>Settings<small>Account information</small></span></button><button class="account-dropdown-item logout-item" role="menuitem" data-action="logout">${icon('logout')}<span>Log out</span></button></div></div>`;
}
function setAccountMenu(open,focusFirst=false){
  state.accountMenu=open;
  const toggle=$('#account-menu-toggle'),dropdown=$('#account-dropdown');
  if(!toggle||!dropdown)return;
  toggle.setAttribute('aria-expanded',String(open));dropdown.hidden=!open;
  if(open){state.notifications=false;$('[data-action="notifications"]')?.setAttribute('aria-expanded','false');$('.notification-panel')?.remove();if(focusFirst)$('[role="menuitem"]',dropdown)?.focus();}
}
document.addEventListener('click',event=>{
  if(state.accountMenu&&!event.target.closest('.account-control'))setAccountMenu(false);
});
document.addEventListener('focusin',event=>{
  if(state.accountMenu&&!event.target.closest('.account-control'))setAccountMenu(false);
});
document.addEventListener('keydown',event=>{
  const toggle=$('#account-menu-toggle');
  if(event.target===toggle&&['ArrowDown','ArrowUp'].includes(event.key)){
    event.preventDefault();setAccountMenu(true,true);
    if(event.key==='ArrowUp')$('#account-dropdown [role="menuitem"]:last-child')?.focus();
    return;
  }
  if(!state.accountMenu)return;
  if(event.key==='Escape'){event.preventDefault();setAccountMenu(false);toggle?.focus();return;}
  if(!event.target.closest('#account-dropdown')||!['ArrowDown','ArrowUp','Home','End'].includes(event.key))return;
  event.preventDefault();
  const items=[...document.querySelectorAll('#account-dropdown [role="menuitem"]')],index=items.indexOf(document.activeElement);
  const next=event.key==='Home'?0:event.key==='End'?items.length-1:(index+(event.key==='ArrowDown'?1:-1)+items.length)%items.length;
  items[next]?.focus();
});
function heading(title,subtitle,action='',extra=''){return `<div class="page-heading"><div><h1>${title}</h1><p>${subtitle}</p></div><div class="heading-actions">${extra}${action}</div></div>`;}
const bookButton=(label='New appointment')=>`<button class="button primary" data-action="book">${icon('plus')}${label}</button>`;
function pageContent(){switch(state.view){case'dashboard':return dashboard();case'appointments':case'history':return appointmentPage();case'accounts':return accountsPage();case'service-history':return serviceHistoryPage();case'patients':return patientsPage();case'schedule':return schedulePage();case'dentists':return dentistsPage();case'followups':return isAdmin()?followupsPage():patientFollowupsPage();case'services':return servicesPage();case'profile':return profilePage();}}
function stats(){const a=state.data.appointments;return `<div class="stats">${[['Total appointments','calendar','',a.length,'All recorded appointments'],['Pending','clock','amber',a.filter(x=>x.status==='Pending').length,'Awaiting confirmation'],['Approved','check','green',a.filter(x=>x.status==='Approved').length,'Confirmed appointments'],['Completed','shield','purple',a.filter(x=>x.status==='Completed').length,'Visits completed'],['Cancelled','x','red',a.filter(x=>x.status==='Cancelled').length,'Cancelled appointments']].map(([label,i,color,num,caption])=>`<div class="stat"><div class="stat-top">${label}<span class="stat-icon ${color}">${icon(i)}</span></div><div class="stat-number">${String(num).padStart(2,'0')}</div><div class="stat-caption">${caption}</div></div>`).join('')}</div>`;}
function dashboard(){return heading(isAdmin()?'A brighter day starts here.':`Welcome back, ${esc(state.user.name.split(' ')[0])}.`,isAdmin()?"Here’s what’s happening at your clinic today.":'Your smile, your schedule. Let’s take care of both.',bookButton(isAdmin()?'New appointment':'Book appointment'),`<button class="button" data-nav="schedule">${icon('calendar')}View schedule</button>`)+(!isAdmin()?`<div class="patient-banner"><div><div class="eyebrow mb-2">Your dental care, connected</div><h2>A healthy smile is always a good plan.</h2><p>Book your next visit, follow your care plan,<br>and keep your dental history in one place.</p></div>${icon('tooth')}</div>`:'')+stats()+`<div class="dashboard-grid"><div><section class="panel"><div class="panel-heading"><div><h2 class="panel-title">${isAdmin()?"Today’s appointments":'Your upcoming appointments'}</h2><div class="panel-subtitle">${isAdmin()?dateFormat(state.selectedDate,{weekday:'long',month:'long',day:'numeric',year:'numeric'}):'A little planning for a healthier smile'}</div></div><button class="text-link" data-nav="appointments">View all appointments ${icon('arrow')}</button></div>${appointmentTabs()}<div class="table-toolbar" style="padding-top:17px">${searchInput()}<select class="filter-select" id="service-filter" aria-label="Filter by service">${serviceOptions()}</select></div><div id="appointment-table">${appointmentTable(true)}</div></section><div class="bottom-grid">${activityPanel()}${distributionPanel()}</div></div><aside class="dashboard-aside"><section class="panel"><div class="panel-heading"><h2 class="panel-title">Appointment calendar</h2>${icon('calendar')}</div><div id="mini-calendar">${miniCalendar()}</div></section>${upcomingPanel()}<div class="soft-banner"><h3>Healthy smiles.<br>Happier patients.</h3><p>A thoughtful follow-up goes a long way. Keep your patients’ care on track.</p><button class="text-link" data-nav="followups">${isAdmin()?'Manage follow-ups':'View follow up appointments'} ${icon('arrow')}</button>${icon('tooth')}</div></aside></div>`;}
function appointmentTabs(){return `<div class="tabs" role="tablist" aria-label="Appointment status">${['All appointments','Pending','Approved','Completed','Cancelled'].map(t=>`<button class="tab ${state.tab===t?'active':''}" role="tab" aria-selected="${state.tab===t}" data-tab="${t}">${t}${t==='Pending'&&state.view!=='dashboard'?` <span>${state.data.appointments.filter(a=>a.status==='Pending'||pendingRequest(a)).length}</span>`:''}</button>`).join('')}</div>`;}
function searchInput(placeholder='Search appointments…'){return `<label class="search">${icon('search')}<input id="search-input" type="search" placeholder="${placeholder}" aria-label="${placeholder}" value="${esc(state.search)}"></label>`;}
function serviceOptions(){return ['All services',...state.data.services.map(s=>s.name)].map(s=>`<option ${state.filter===s?'selected':''}>${esc(s)}</option>`).join('');}
function filteredAppointments(dashboard=false){return state.data.appointments.filter(a=>(!dashboard||(isAdmin()?a.date===state.selectedDate:a.date>=localDate()&&['Pending','Approved'].includes(a.status)))&&(state.tab==='All appointments'||(state.tab==='Pending'?a.status==='Pending'||pendingRequest(a):a.status===state.tab))&&(state.filter==='All services'||a.service===state.filter)&&`${a.patient_name} ${a.service} ${a.id} ${a.date}`.toLowerCase().includes(state.search.toLowerCase())).sort((a,b)=>dashboard?a.date.localeCompare(b.date)||a.time.localeCompare(b.time):b.date.localeCompare(a.date)||a.time.localeCompare(b.time));}
function appointmentTable(dashboard=false){if(state.view==='service-history')return serviceHistoryTable();const filtered=filteredAppointments(dashboard),limit=dashboard?5:9,pages=Math.max(1,Math.ceil(filtered.length/limit));state.page=Math.min(state.page,pages);const rows=filtered.slice((state.page-1)*limit,state.page*limit);return `<div class="table-scroll"><table><thead><tr><th>${isAdmin()?'Patient':'Appointment'}</th><th>Dental service</th>${!dashboard||!isAdmin()?'<th>Date</th>':''}<th>Time</th><th>Status</th><th aria-label="Actions"></th></tr></thead><tbody>${rows.map(a=>`<tr><td>${isAdmin()?person(a.patient_name,'Patient #'+String(a.patient_id).padStart(4,'0'),a.patient_id):`<strong class="service-text">#PD-${String(a.id).padStart(4,'0')}</strong>`}</td><td><span class="service-text">${esc(a.service)}</span><small class="dentist-caption">${esc(a.dentist_name)}</small>${a.request?`<small class="request-note">${esc(a.request)} requested</small>`:''}</td>${!dashboard||!isAdmin()?`<td>${dateFormat(a.date)}</td>`:''}<td><span class="small-time">${icon('clock')}${timeFormat(a.time)}</span></td><td>${pendingRequest(a)?statusBadge('Pending')+`<small class="dentist-caption">Change request · Visit ${esc(a.status.toLowerCase())}</small>`:statusBadge(a.status)}</td><td><button class="icon-btn" data-detail="${a.id}" aria-label="View appointment ${a.id}">${icon('more')}</button></td></tr>`).join('')}</tbody></table>${!rows.length?`<div class="empty">${icon('calendar')}No appointments match this view.</div>`:''}</div><div class="table-footer"><span>${filtered.length?`Showing ${(state.page-1)*limit+1}–${Math.min(state.page*limit,filtered.length)} of ${filtered.length} appointments`:'No appointments to show'}</span><div class="pager"><button class="button" data-page="${state.page-1}" ${state.page<=1?'disabled':''} aria-label="Previous page">${icon('left')}</button><span class="page-num">${state.page}</span><button class="button" data-page="${state.page+1}" ${state.page>=pages?'disabled':''} aria-label="Next page">${icon('chevron')}</button></div></div>`;}
function miniCalendar(){
  const y=state.calendar.getFullYear(),m=state.calendar.getMonth(),offset=new Date(y,m,1).getDay(),days=[];
  for(let i=0;i<42;i++){
    const d=new Date(y,m,i-offset+1),date=localDate(d),appointments=state.data.appointments.filter(a=>a.date===date);
    const statuses=['Approved','Pending','Cancelled','Completed'].filter(status=>appointments.some(a=>a.status===status));
    const description=statuses.map(status=>`${appointments.filter(a=>a.status===status).length} ${status.toLowerCase()}`).join(', ');
    days.push(`<button class="day ${d.getMonth()!==m?'outside':''} ${date===localDate()?'today':''} ${date===state.selectedDate?'selected':''}" data-date="${date}" aria-label="${dateFormat(date,{month:'long',day:'numeric',year:'numeric'})}${description?', '+description:''}" title="${description||'No appointments'}" ${date===state.selectedDate?'aria-pressed="true"':''}>${d.getDate()}<span class="calendar-dots" aria-hidden="true">${statuses.map(status=>`<i class="calendar-dot ${status.toLowerCase()}"></i>`).join('')}</span></button>`);
  }
  return `<div class="calendar-head"><strong>${state.calendar.toLocaleDateString('en-US',{month:'long',year:'numeric'})}</strong><div><button class="icon-btn" data-month="-1" aria-label="Previous month">${icon('left')}</button><button class="icon-btn" data-month="1" aria-label="Next month">${icon('chevron')}</button></div></div><div class="calendar-grid">${['S','M','T','W','T','F','S'].map(d=>`<span class="weekday">${d}</span>`).join('')}${days.join('')}</div><div class="calendar-legend">${['Approved','Pending','Cancelled','Completed'].map(status=>`<span><i class="calendar-dot ${status.toLowerCase()}"></i>${status}</span>`).join('')}</div>`;
}
function upcomingPanel(){const upcoming=state.data.appointments.filter(a=>new Date(a.date+'T'+a.time)>new Date()&&a.status==='Approved').sort((a,b)=>a.date.localeCompare(b.date)||a.time.localeCompare(b.time)).slice(0,3);return `<section class="panel"><div class="panel-heading"><h2 class="panel-title">Coming up next</h2><span class="badge-status approved">${upcoming.length} visits</span></div><div class="schedule-list">${upcoming.map(a=>`<div class="schedule-item"><div class="schedule-time">${timeFormat(a.time).replace(' ','<br>')}</div><div class="schedule-detail"><button class="text-link" data-detail="${a.id}"><strong>${esc(isAdmin()?a.patient_name:a.service)}</strong></button><p>${isAdmin()?esc(a.service)+' · ':''}${dateFormat(a.date,{month:'short',day:'numeric'})}</p>${statusBadge(a.status)}</div></div>`).join('')||'<div class="empty">No confirmed visits yet.</div>'}</div></section>`;}
function activityPanel(){const requests=state.data.appointments.filter(a=>a.request);const items=isAdmin()?requests.slice(0,3).map(a=>`<div class="activity"><div class="activity-symbol">${icon('repeat')}</div><div><p><strong>${esc(a.patient_name)}</strong> requested ${a.request.toLowerCase()}.</p><button class="text-link" data-detail="${a.id}">Review request ${icon('arrow')}</button></div></div>`):state.data.notifications.slice(0,3).map(n=>`<div class="activity"><div class="activity-symbol">${icon('bell')}</div><div><p>${esc(n.message)}</p><small>${esc(n.created.slice(0,10))}</small></div></div>`);return `<section class="panel"><div class="panel-heading"><div><h2 class="panel-title">${isAdmin()?'Patient requests':'Care updates'}</h2><div class="panel-subtitle">${isAdmin()?'Keep every patient in the loop':'The latest from your clinic'}</div></div>${icon('repeat')}</div><div class="activity-list">${items.join('')||'<div class="empty">You’re all caught up.</div>'}</div></section>`;}
function distributionPanel(){const a=state.data.appointments,colors=['#7fa7f3','#edc675','#91cdb9','#b2a5e1'],statuses=['Approved','Pending','Completed','Cancelled'];return `<section class="panel"><div class="panel-heading"><div><h2 class="panel-title">Appointment overview</h2><div class="panel-subtitle">A snapshot of all your appointments</div></div>${icon('grid')}</div><div class="distribution"><div class="distribution-bar">${statuses.map((s,i)=>`<span style="flex:${a.filter(x=>x.status===s).length||.01};background:${colors[i]}"></span>`).join('')}</div>${statuses.map((s,i)=>`<div class="dist-row"><span><i class="legend-dot" style="background:${colors[i]}"></i>${s}</span><strong>${a.filter(x=>x.status===s).length} <span style="color:#a5aebb;font-weight:400;margin-left:12px">${a.length?Math.round(a.filter(x=>x.status===s).length/a.length*100):0}%</span></strong></div>`).join('')}</div></section>`;}
function appointmentPage(){const history=state.view==='history';return heading(history?'Your care, over time.':isAdmin()?'Appointments':'My appointments',history?'Your visit records and pending appointment requests.':'Every visit, organized in one place.',history?'':bookButton())+`<section class="panel"><div class="panel-heading"><h2 class="panel-title">${history?'Appointment history':'All appointments'}</h2><span class="panel-subtitle">${state.data.appointments.length} total records</span></div>${appointmentTabs()}<div class="table-toolbar" style="padding-top:20px">${searchInput()}<select class="filter-select" id="service-filter" aria-label="Filter by service">${serviceOptions()}</select></div><div id="appointment-table">${appointmentTable()}</div></section>`;}
function patientsPage(){const patients=state.data.patients.filter(p=>`${p.name} ${p.email} ${p.phone}`.toLowerCase().includes(state.search.toLowerCase()));return heading('Patients','A little familiarity makes every visit better.',bookButton())+`<section class="panel"><div class="panel-heading"><h2 class="panel-title">Patient directory</h2>${searchInput('Search patients…')}</div><div class="table-scroll" id="patients-table">${patientTable(patients)}</div></section>`;}
function patientTable(patients){return `<table><thead><tr><th>Patient</th><th>Phone number</th><th>Appointments</th><th>Last visit</th><th></th></tr></thead><tbody>${patients.map(p=>{const visits=state.data.appointments.filter(a=>a.patient_id===p.id),completed=visits.filter(a=>a.status==='Completed').sort((a,b)=>b.date.localeCompare(a.date));return `<tr><td>${person(p.name,p.email,p.id)}</td><td>${esc(p.phone||'—')}</td><td>${visits.length} visits</td><td>${completed.length?dateFormat(completed[0].date):'No completed visits'}</td><td><button class="text-link" data-patient="${p.id}">View history ${icon('arrow')}</button></td></tr>`;}).join('')}</tbody></table>${!patients.length?'<div class="empty">No patients found.</div>':''}`;}
function servicesPage(){return heading('Care for every smile.','Explore our services and find the right care for you.')+`<div class="services-grid">${state.data.services.map(s=>`<section class="service-card"><span class="stat-icon">${icon('tooth')}</span><h3>${esc(s.name)}</h3><p>${esc(s.description)}</p><div class="service-meta"><span>${s.duration} min · Initial appointment</span><strong>${money(s.price)}</strong></div><button class="button ${isAdmin()?'':'primary'}" data-service="${s.id}">${icon('plus')}Book appointment</button></section>`).join('')}</div><p class="form-hint section-gap">Prices are estimates for the listed service. Treatment needs and final costs are discussed with your dentist.</p>`;}
function followupPlan(){
  return `<section class="panel"><div class="panel-heading"><div><h2 class="panel-title">Follow-up appointments from your administrator</h2><div class="panel-subtitle">Recommended visits, dates, and your assigned dentist.</div></div><span class="panel-subtitle">${state.data.followups.length} recommendations</span></div>${state.data.followups.map(f=>{
    const a=state.data.appointments.find(a=>a.id===f.appointment_id),canReschedule=a&&['Pending','Approved'].includes(a.status)&&new Date(a.date+'T'+a.time)>new Date();
    return `<div class="followup-card"><div class="stat-icon">${icon('repeat')}</div><div class="reschedule-content"><h3>${esc(f.service)}${isAdmin()?' · '+esc(f.patient_name):''}</h3><p><strong>Recommended date:</strong> ${dateFormat(f.date)}<br><strong>Dentist:</strong> ${esc(a?.dentist_name||f.dentist_name)}${f.note?'<br>'+esc(f.note):''}</p>${a?`<p class="mt-2"><strong>Appointment:</strong> ${dateFormat(a.date)} at ${timeFormat(a.time)} &nbsp; ${statusBadge(a.status)}</p>`:'<p class="form-hint mt-2">Choose an available time to confirm your visit request.</p>'}${a?.request?`<small class="request-note">${esc(a.request)} request pending clinic review</small>`:''}<div class="detail-actions">${a?`<button class="button" data-detail="${a.id}">View appointment</button>${canReschedule&&!isAdmin()?`<button class="button" data-reschedule="${a.id}">Request reschedule</button>`:''}`:`<button class="button primary" data-followup="${f.id}">Schedule visit</button>`}</div></div></div>`;
  }).join('')||`<div class="empty">${icon('repeat')}No follow-up appointments provided yet.</div>`}</section>`;
}
function followupsPage(){return heading('Thoughtful care continues.','Recommend the next visit, date, and dentist for each patient.',`<button class="button primary" data-action="followup">${icon('plus')}Recommend follow-up</button>`)+followupPlan();}
function schedulePage(){const start=new Date();start.setDate(start.getDate()-start.getDay()+1+state.week*7);const days=Array.from({length:7},(_,i)=>{const d=new Date(start);d.setDate(d.getDate()+i);return localDate(d);});return heading('A clear view of the week.','Plan ahead with your clinic’s appointment schedule.',bookButton())+`<section class="panel"><div class="panel-heading"><div><h2 class="panel-title">${dateFormat(days[0],{month:'long',day:'numeric'})} – ${dateFormat(days[6],{month:'long',day:'numeric',year:'numeric'})}</h2><div class="panel-subtitle">Monday–Saturday · 9:00 AM–5:00 PM · 12:00–1:00 PM lunch</div></div><div class="heading-actions"><button class="button" data-week="-1" aria-label="Previous week">${icon('left')}</button><button class="button" data-action="this-week">Today</button><button class="button" data-week="1" aria-label="Next week">${icon('chevron')}</button></div></div><div class="table-scroll"><div class="week-schedule">${days.map(d=>`<div class="week-col"><div class="week-day ${d===localDate()?'today':''}">${dateFormat(d,{weekday:'short'})}<strong>${new Date(d+'T12:00:00').getDate()}</strong></div>${state.data.appointments.filter(a=>a.date===d&&a.status!=='Cancelled').sort((a,b)=>a.time.localeCompare(b.time)).map(a=>`<button class="week-event" data-detail="${a.id}">${timeFormat(a.time)}<strong>${esc(isAdmin()?a.patient_name:a.service)}</strong><span>${esc(isAdmin()?a.service:a.status)}</span></button>`).join('')}${new Date(d+'T12:00:00').getDay()===0?'<div class="empty">Clinic closed</div>':''}</div>`).join('')}</div></div></section>`;}
function profilePage(){return heading('Account information','Keep your contact information up to date.')+`<section class="panel"><form class="form-section" id="profile-form"><h3>Personal information</h3><p>Your clinic uses these details to identify your appointment records.</p><div class="profile-photo-editor"><div id="profile-picture-preview">${profileAvatar(state.user)}</div><div><h4>Profile picture</h4><p class="form-hint">JPG, PNG, or WebP up to 2 MB. Photos are cropped to a square.</p><div class="profile-photo-actions"><button type="button" class="button" id="choose-profile-photo">${icon('plus')}Change picture</button><button type="button" class="button" id="remove-profile-photo" ${state.user.photo_url?'':'hidden'}>Remove picture</button></div><input id="profile-photo-input" type="file" accept="image/jpeg,image/png,image/webp" hidden aria-label="Choose profile picture"><span id="profile-photo-status" class="form-hint" role="status" aria-live="polite"></span></div></div><div class="form-error" id="photo-error"></div><div class="mb-3"><label class="form-label" for="profile-name">Full name</label><input id="profile-name" class="form-control" name="name" value="${esc(state.user.name)}" minlength="2" maxlength="100" required></div>${state.user.username?`<div class="mb-3"><label class="form-label" for="profile-username">Username</label><input id="profile-username" class="form-control" value="${esc(state.user.username)}" disabled></div>`:''}<div class="mb-3"><label class="form-label" for="profile-email">Email address</label><input id="profile-email" class="form-control" value="${esc(state.user.email)}" type="email" disabled><div class="form-hint mt-2">Your email is your account identifier.</div></div><div class="mb-4"><label class="form-label" for="profile-phone">Phone number</label><input id="profile-phone" name="phone" class="form-control" value="${esc(state.user.phone)}" maxlength="30" type="tel"></div><div class="form-error" id="profile-error"></div><button class="button primary" type="submit">Save changes</button></form></section>`;}
function notificationsView(){return `<section class="notification-panel" aria-label="Notifications"><div class="panel-heading"><h2 class="panel-title">Notifications</h2><button class="text-link" data-action="read-notifications">Mark all as read</button></div>${state.data.notifications.map(n=>`<div class="activity ${n.seen?'':'unread'}"><div class="activity-symbol">${icon('bell')}</div><div><p>${esc(n.message)}</p><small>${esc(n.created)} UTC</small></div></div>`).join('')||'<div class="empty">No notifications yet.</div>'}</section>`;}
async function navigate(view){setAccountMenu(false);if(view==='schedule'&&!isAdmin()){state.view='schedule';}else state.view=view;state.tab='All appointments';state.search='';state.filter='All services';state.page=1;state.notifications=false;if(view==='accounts')await refresh();else render();window.scrollTo(0,0);}
function bindEvents(){
  app.onclick=async event=>{const el=event.target.closest('button');if(!el)return;try{
    if(el.dataset.nav){await navigate(el.dataset.nav);return;}
    if(el.dataset.tab){state.tab=el.dataset.tab;state.page=1;render();return;}
    if(el.dataset.page){state.page=Number(el.dataset.page);$('#appointment-table').innerHTML=appointmentTable(state.view==='dashboard');return;}
    if(el.dataset.month){state.calendar.setMonth(state.calendar.getMonth()+Number(el.dataset.month));$('#mini-calendar').innerHTML=miniCalendar();return;}
    if(el.dataset.date){state.selectedDate=el.dataset.date;state.page=1;render();return;}
    if(el.dataset.detail){appointmentDetail(Number(el.dataset.detail));return;}
    if(el.dataset.promote){promoteAccountModal(Number(el.dataset.promote));return;}
    if(el.dataset.patient){patientHistory(Number(el.dataset.patient));return;}
    if(el.dataset.dentist){bookingModal({dentist_id:Number(el.dataset.dentist)});return;}
    if(el.dataset.availability){await api('/dentists/'+el.dataset.availability,'PATCH',{available:el.dataset.available==='true'});await refresh();toast('Dentist availability updated.');return;}
    if(el.dataset.reschedule){const a=state.data.appointments.find(a=>a.id===Number(el.dataset.reschedule));bookingModal({appointment:a,date:a.date});return;}
    if(el.dataset.proposal){await api('/reschedules/'+el.dataset.proposal,'PATCH',{decision:el.dataset.decision});await refresh();toast('Your response was sent to the clinic.');return;}
    if(el.dataset.service){bookingModal({service_id:Number(el.dataset.service)});return;}
    if(el.dataset.followup){const f=state.data.followups.find(f=>f.id===Number(el.dataset.followup));bookingModal({service_id:f.service_id,patient_id:f.patient_id,followup_id:f.id,dentist_id:f.dentist_id,date:f.date>=localDate()?f.date:localDate()});return;}
    if(el.dataset.week){state.week+=Number(el.dataset.week);render();return;}
    switch(el.dataset.action){case'account-menu':setAccountMenu(!state.accountMenu);break;case'book':bookingModal();break;case'followup':followupModal();break;case'this-week':state.week=0;render();break;case'menu':$('.sidebar').classList.add('open');app.insertAdjacentHTML('beforeend','<div class="sidebar-shade"></div>');$('.sidebar-shade').onclick=()=>{$('.sidebar').classList.remove('open');$('.sidebar-shade').remove();};break;case'logout':setAccountMenu(false);await api('/logout','POST',{});state.user=null;state.data=null;closeModal();renderAuth();break;case'notifications':setAccountMenu(false);state.notifications=!state.notifications;render();break;case'read-notifications':await api('/notifications/read','POST',{});await refresh();break;}
  }catch(error){toast(error.message);}};
  $('#search-input')?.addEventListener('input',event=>{state.search=event.target.value;state.page=1;if(state.view==='accounts')$('#accounts-table').innerHTML=accountsTable();else if(state.view==='patients')$('#patients-table').innerHTML=patientTable(state.data.patients.filter(p=>`${p.name} ${p.email} ${p.phone}`.toLowerCase().includes(state.search.toLowerCase())));else $('#appointment-table').innerHTML=appointmentTable(state.view==='dashboard');});
  $('#service-filter')?.addEventListener('change',event=>{state.filter=event.target.value;state.page=1;$('#appointment-table').innerHTML=appointmentTable(state.view==='dashboard');});
  bindProfilePhoto();
  $('#profile-form')?.addEventListener('submit',async event=>{event.preventDefault();const button=$('button[type=submit]',event.target);button.disabled=true;try{await api('/profile','PATCH',Object.fromEntries(new FormData(event.target)));await refresh();toast('Your profile has been updated.');}catch(error){$('#profile-error').textContent=error.message;}finally{button.disabled=false;}});
}
let previousFocus,modalCleanup;
function showModal(title,body,footer=''){document.removeEventListener('keydown',modalCleanup);previousFocus=document.activeElement;$('#modal-root').innerHTML=`<div class="modal-overlay"><section class="app-modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-heading"><h2 id="modal-title">${title}</h2><button class="icon-btn" data-close aria-label="Close dialog">${icon('close')}</button></div><div class="modal-body">${body}</div>${footer?`<div class="modal-footer-custom">${footer}</div>`:''}</section></div>`;document.body.style.overflow='hidden';$('#modal-root').onclick=event=>{if(event.target.closest('[data-close]')||event.target.classList.contains('modal-overlay'))closeModal();};const modal=$('.app-modal');$('input:not([disabled]),select,button',modal)?.focus();modalCleanup=e=>{if(e.key==='Escape')closeModal();if(e.key==='Tab'){const focusable=[...modal.querySelectorAll('button:not([disabled]),input:not([disabled]),select,textarea,a[href]')];const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}};document.addEventListener('keydown',modalCleanup);}
function closeModal(){document.removeEventListener('keydown',modalCleanup);$('#modal-root').innerHTML='';document.body.style.overflow='';previousFocus?.focus();}
function selectServices(selected){return state.data.services.map(s=>`<option value="${s.id}" ${s.id===Number(selected)?'selected':''}>${esc(s.name)} · ${money(s.price)}</option>`).join('');}
function selectPatients(selected){return state.data.patients.map(p=>`<option value="${p.id}" ${p.id===Number(selected)?'selected':''}>${esc(p.name)}</option>`).join('');}
async function bookingModal(options={}){
  const reschedule=options.appointment,proposal=!!options.proposal;let selectedTime='';
  showModal(reschedule?(proposal?'Propose a new time':'Request a new time'):options.followup_id?'Schedule your follow-up':'Book an appointment',`<form id="booking-form">${isAdmin()?`<div class="mb-3"><label class="form-label" for="book-patient">Patient</label><select id="book-patient" class="form-select" name="patient_id" ${options.followup_id?'disabled':''}>${selectPatients(options.patient_id)}</select></div>`:''}<div class="mb-3"><label class="form-label" for="book-service">Dental service</label><select class="form-select" name="service_id" id="book-service" ${reschedule||options.followup_id?'disabled':''}>${selectServices(reschedule?.service_id||options.service_id)}</select></div><div class="mb-3"><label class="form-label" for="book-dentist">Choose your dentist</label><select class="form-select" name="dentist_id" id="book-dentist" ${reschedule||options.followup_id?'disabled':''}>${state.data.dentists.map(d=>`<option value="${d.id}" ${d.id===Number(reschedule?.dentist_id||options.dentist_id||1)?'selected':''} ${!d.available?'disabled':''}>${esc(d.name)} · ${d.available?'Available':'Not available'}</option>`).join('')}</select><div class="form-hint mt-2">Availability is checked for the selected dentist and time.</div></div><div class="mb-3"><label class="form-label" for="book-date">Appointment date</label><input class="form-control" id="book-date" name="date" type="date" value="${options.date||localDate()}" min="${localDate()}" max="${localDate(new Date(Date.now()+90*86400000))}" required></div><label class="form-label">Available times <span class="form-hint">· 30-minute appointments</span></label><div class="slots" id="booking-slots" role="group" aria-label="Available appointment times"></div><p class="form-hint mt-2">Monday–Saturday · Closed for lunch 12:00–1:00 PM</p>${!reschedule?'<div class="mt-3"><label class="form-label" for="book-notes">Notes for the clinic <span class="form-hint">(optional)</span></label><textarea class="form-control" id="book-notes" name="notes" rows="2" maxlength="1000" placeholder="Anything you’d like your dentist to know?"></textarea></div>':''}<div class="info-box mt-3">${reschedule?(proposal?'The patient will see your proposed time in Follow up appointments and can accept or decline. The original booking stays in place until acceptance.':'Your current appointment stays in place until the clinic accepts your request. The requested slot is subject to availability.'):'Your appointment will be pending until the clinic confirms it. You’ll receive an update in your notifications.'}</div><div class="form-error" id="booking-error"></div></form>`,`<button class="button" data-close>Cancel</button><button class="button primary" id="submit-booking" form="booking-form" type="submit">${reschedule?(proposal?'Send proposed time':'Send request'):'Book appointment'} ${icon('arrow')}</button>`);
  const form=$('#booking-form');let slotLoad=0;
  async function loadSlots(){const load=++slotLoad;selectedTime='';$('#booking-slots').innerHTML='<span class="form-hint">Loading available times…</span>';try{const data=await api(`/slots?date=${$('#book-date').value}&exclude=${reschedule?.id||0}&dentist=${$('#book-dentist').value}&patient=${options.patient_id||reschedule?.patient_id||$('#book-patient')?.value||0}`);if(load!==slotLoad||!$('#booking-slots'))return;$('#booking-slots').innerHTML=data.slots.map(s=>`<button type="button" class="slot" data-time="${s.time}" ${!s.available?'disabled':''} aria-pressed="false">${timeFormat(s.time)}</button>`).join('');$('#booking-slots').onclick=e=>{const b=e.target.closest('[data-time]');if(!b||b.disabled)return;selectedTime=b.dataset.time;$('#booking-slots').querySelectorAll('button').forEach(x=>{x.classList.toggle('selected',x===b);x.setAttribute('aria-pressed',String(x===b));});};}catch(error){if($('#booking-error'))$('#booking-error').textContent=error.message;}}
  $('#book-dentist').addEventListener('change',loadSlots);$('#book-patient')?.addEventListener('change',loadSlots);$('#book-date').addEventListener('change',loadSlots);await loadSlots();
  form.onsubmit=async event=>{event.preventDefault();const error=$('#booking-error');error.textContent='';if(!selectedTime){error.textContent='Please select an available time.';return;}const submit=$('#submit-booking');submit.disabled=true;try{const body={...Object.fromEntries(new FormData(form)),service_id:$('#book-service').value,dentist_id:$('#book-dentist').value,patient_id:options.patient_id||$('#book-patient')?.value,time:selectedTime,followup_id:options.followup_id};if(reschedule){await api('/appointments/'+reschedule.id,'PATCH',{...(proposal?{propose:true}:{request:'Reschedule'}),date:body.date,time:selectedTime});}else await api('/appointments','POST',body);closeModal();await refresh();toast(reschedule?(proposal?'Proposed time sent to the patient.':'Reschedule request sent to your clinic.'):'Appointment booked. Awaiting clinic approval.');}catch(e){error.textContent=e.message;submit.disabled=false;}};
}
function appointmentDetail(id){const a=state.data.appointments.find(a=>a.id===id);if(!a)return;const active=['Pending','Approved'].includes(a.status);showModal(`Appointment #PD-${String(a.id).padStart(4,'0')}`,`${person(a.patient_name,a.patient_email,a.patient_id)}<div class="detail-grid"><div><small>Dental service</small><strong>${esc(a.service)}</strong></div><div><small>Status</small>${statusBadge(a.status)}</div><div><small>Appointment date</small><strong>${dateFormat(a.date)}</strong></div><div><small>Time</small><strong>${timeFormat(a.time)} · 30 minutes</strong></div><div><small>Dentist</small><strong>${esc(a.dentist_name)}</strong></div><div><small>Estimated cost</small><strong>${money(a.price)}</strong></div><div><small>Phone</small><strong>${esc(a.patient_phone||'Not provided')}</strong></div></div>${a.notes?`<div class="info-box"><strong>Patient notes</strong><br>${esc(a.notes)}</div>`:''}${a.request?`<div class="info-box mt-3"><strong>${esc(a.request)} requested</strong>${a.request==='Reschedule'?`<br>Requested time: ${dateFormat(a.requested_date)} at ${timeFormat(a.requested_time)}`:''}<br>${isAdmin()?'Review the request below.':'Your clinic will review your request.'}</div>`:''}<div class="detail-actions">${isAdmin()?`${a.request?'<button class="button primary" data-resolve="accept">Accept request</button><button class="button" data-resolve="decline">Decline request</button>':''}${active?`${a.status==='Pending'?'<button class="button primary" data-status="Approved">Approve appointment</button>':''}${new Date(a.date+'T'+a.time)<=new Date()?'<button class="button" data-status="Completed">Mark completed</button>':''}<button class="button" id="propose-appointment">Propose a new time</button><button class="button danger" data-status="Cancelled">Cancel appointment</button>`:''}<button class="button" id="recommend-from-appointment">${icon('repeat')}Recommend follow-up</button>`:active&&new Date(a.date+'T'+a.time)>new Date()?'<button class="button primary" id="reschedule-appointment">Request reschedule</button><button class="button danger" id="cancel-appointment">Request cancellation</button>':''}</div><div id="detail-error" class="form-error"></div>`);
  const perform=async body=>{try{await api('/appointments/'+id,'PATCH',body);closeModal();await refresh();toast('Appointment updated.');}catch(error){if($('#detail-error'))$('#detail-error').textContent=error.message;else toast(error.message);}};
  document.querySelectorAll('[data-status]').forEach(b=>b.onclick=()=>{if(b.dataset.status==='Cancelled'){showModal('Cancel this appointment?',`<p class="form-hint">This will cancel ${esc(a.patient_name)}’s appointment on ${dateFormat(a.date)} at ${timeFormat(a.time)} and notify the patient.</p>`,`<button class="button" data-close>Keep appointment</button><button class="button danger" id="confirm-cancel">Cancel appointment</button>`);$('#confirm-cancel').onclick=()=>perform({status:'Cancelled'});}else perform({status:b.dataset.status});});
  document.querySelectorAll('[data-resolve]').forEach(b=>b.onclick=()=>perform({resolve:b.dataset.resolve}));
  $('#propose-appointment')?.addEventListener('click',()=>{closeModal();bookingModal({appointment:a,date:a.date,patient_id:a.patient_id,proposal:true});});
  $('#reschedule-appointment')?.addEventListener('click',()=>{closeModal();bookingModal({appointment:a,date:a.date});});
  $('#cancel-appointment')?.addEventListener('click',()=>perform({request:'Cancellation'}));
  $('#recommend-from-appointment')?.addEventListener('click',()=>{closeModal();followupModal(a.patient_id,a.service_id,a.dentist_id);});
}
function patientHistory(id){const p=state.data.patients.find(p=>p.id===id),visits=state.data.appointments.filter(a=>a.patient_id===id);showModal('Patient appointment history',`${person(p.name,p.email,p.id)}<p class="form-hint mt-3">${esc(p.phone||'No phone number on file')} · ${visits.length} appointment records</p>${visits.map(a=>`<div class="activity"><div class="activity-symbol">${icon('tooth')}</div><div style="flex:1"><p><strong>${esc(a.service)}</strong></p><small>${dateFormat(a.date)} · ${timeFormat(a.time)}</small></div>${statusBadge(a.status)}</div>`).join('')||'<div class="empty">No appointment history yet.</div>'}`);}
function followupModal(patient,service,dentist=1){showModal('Recommend a follow-up',`<form id="followup-form"><div class="mb-3"><label class="form-label" for="followup-patient">Patient</label><select id="followup-patient" name="patient_id" class="form-select">${selectPatients(patient)}</select></div><div class="mb-3"><label class="form-label" for="followup-service">Recommended service</label><select id="followup-service" name="service_id" class="form-select">${selectServices(service)}</select></div><div class="mb-3"><label class="form-label" for="followup-dentist">Assigned dentist</label><select id="followup-dentist" name="dentist_id" class="form-select">${state.data.dentists.map(d=>`<option value="${d.id}" ${d.id===Number(dentist)?'selected':''}>${esc(d.name)}${d.available?'':' (not currently available)'}</option>`).join('')}</select></div><div class="mb-3"><label class="form-label" for="followup-date">Recommended date</label><input id="followup-date" class="form-control" name="date" type="date" min="${localDate()}" max="${localDate(new Date(Date.now()+90*86400000))}" required></div><div class="mb-3"><label class="form-label" for="followup-note">Care instructions</label><textarea id="followup-note" class="form-control" name="note" rows="3" maxlength="1000" placeholder="Help the patient prepare for their next visit."></textarea></div><div class="info-box">This recommendation will appear in the patient’s care plan and notifications. The patient can then choose an available appointment.</div><div class="form-error" id="followup-error"></div></form>`,`<button class="button" data-close>Cancel</button><button class="button primary" type="submit" form="followup-form">Send recommendation</button>`);$('#followup-form').onsubmit=async e=>{e.preventDefault();const submit=$('[form="followup-form"]');submit.disabled=true;try{await api('/followups','POST',Object.fromEntries(new FormData(e.target)));closeModal();await refresh();toast('Follow-up recommendation sent.');}catch(error){$('#followup-error').textContent=error.message;submit.disabled=false;}};}
function renderAuth(mode='login',message=''){state.accountMenu=false;
  const resetToken=new URLSearchParams(location.search).get('reset');if(resetToken)mode='reset';
  app.innerHTML=`<main class="login-screen"><section class="login-art">${brand()}<div class="login-art-copy"><div class="login-pill">${icon('spark')} A little care makes a big difference</div><h1>Good care.<br>Great smiles.<br>All in one place.</h1><p>A simpler way to manage your dental visits, follow your care plan, and keep smiling.</p></div><div class="tooth-art">${icon('tooth')}</div><div class="login-art-footer">© ${new Date().getFullYear()} NB MAGBANUA DENTAL CLINIC · Care beyond the smile.</div></section><section class="login-form-wrap"><div class="login-form"><h2>${{login:'Welcome back.',register:'Your smile starts here.',forgot:'Forgot your password?',reset:'A fresh start.'}[mode]}</h2><p>${{login:'Sign in to stay connected to your dental care.',register:'Create an account to book and manage your visits.',forgot:'Enter your username or email to request a password reset.',reset:'Choose a new password for your account.'}[mode]}</p>${message?`<div class="info-box mb-3">${esc(message)}</div>`:''}<form id="auth-form">${mode==='register'?'<div class="mb-3"><label class="form-label" for="auth-name">Full name</label><input class="form-control" id="auth-name" name="name" autocomplete="name" minlength="2" maxlength="100" placeholder="Alex Morgan" required></div>':''}${mode!=='reset'?`<div class="mb-3"><label class="form-label" for="auth-email">${mode==='register'?'Email address':'Username or email'}</label><input class="form-control" id="auth-email" type="${mode==='register'?'email':'text'}" name="email" autocomplete="${mode==='register'?'email':'username'}" placeholder="${mode==='register'?'you@example.com':'Enter your username or email'}" required></div>`:''}${mode!=='forgot'?`<div class="mb-3"><label class="form-label" for="auth-password">${mode==='reset'?'New password':'Password'}</label><div class="password-field"><input class="form-control" id="auth-password" type="password" name="password" autocomplete="${mode==='login'?'current-password':'new-password'}" ${mode==='login'?'':'minlength="10"'} maxlength="128" placeholder="${mode==='login'?'Enter your password':'At least 10 characters'}" required><button class="password-toggle" type="button" id="password-toggle" aria-label="Show password" aria-controls="auth-password" aria-pressed="false">${icon('eye')}</button></div></div>`:''}${mode==='login'?'<div style="text-align:right" class="mb-4"><button type="button" class="text-link" data-auth="forgot">Forgot password?</button></div>':''}<div class="form-error" id="auth-error"></div><button class="button primary" type="submit">${{login:'Sign in',register:'Create account',forgot:'Request reset',reset:'Update password'}[mode]} ${icon('arrow')}</button></form><div class="login-switch">${mode==='login'?'New to NB MAGBANUA DENTAL CLINIC? <button class="text-link" data-auth="register">Create an account</button>':'<button class="text-link" data-auth="login">Back to sign in</button>'}</div>${mode==='login'?'<div class="demo-box"><p>Quick sign-in</p><div class="demo-actions"><button class="button" data-demo="admin">'+icon('grid')+'Staff workspace</button><button class="button" data-demo="patient">'+icon('users')+'Patient portal</button></div><p style="text-transform:none;letter-spacing:0;margin-top:12px;line-height:1.7">Enter your assigned username and password, then select Sign in · For local testing</p></div>':''}<div id="reset-result"></div></div></section></main>`;
  document.querySelectorAll('[data-auth]').forEach(b=>b.onclick=()=>{history.replaceState(null,'','/');renderAuth(b.dataset.auth);});
  const signIn=async(email,password)=>{const result=await api('/login','POST',{email,password});state.user=result.user;state.view='dashboard';state.tab='All appointments';state.search='';state.filter='All services';state.page=1;await refresh();};
  $('#password-toggle')?.addEventListener('click',()=>{
    const input=$('#auth-password'),toggle=$('#password-toggle'),show=input.type==='password';
    input.type=show?'text':'password';toggle.setAttribute('aria-label',show?'Hide password':'Show password');
    toggle.setAttribute('aria-pressed',String(show));toggle.innerHTML=icon(show?'eyeOff':'eye');
  });
  document.querySelectorAll('[data-demo]').forEach(b=>b.onclick=()=>{
    const identifier=$('#auth-email'),password=$('#auth-password');
    if(!identifier.value.trim())identifier.value=b.dataset.demo==='admin'?'yongco':'dwaynelei';
    if(password.value)$('#auth-form').requestSubmit();else password.focus();
  });
  $('#auth-form').onsubmit=async event=>{event.preventDefault();const button=$('button[type=submit]',event.target);button.disabled=true;$('#auth-error').textContent='';try{const body=Object.fromEntries(new FormData(event.target));if(mode==='login')await signIn(body.email,body.password);if(mode==='register'){const result=await api('/register','POST',body);renderAuth('login',result.message);}if(mode==='forgot'){const result=await api('/forgot-password','POST',body);$('#reset-result').innerHTML=`<div class="info-box mt-3">${esc(result.message)}${result.resetUrl?`<br><a href="${esc(result.resetUrl)}">Open local testing reset link →</a>`:''}</div>`;}if(mode==='reset'){const result=await api('/reset-password','POST',{token:resetToken,password:body.password});history.replaceState(null,'','/');renderAuth('login',result.message);}}catch(error){$('#auth-error').textContent=error.message;}finally{button.disabled=false;}};
}
async function init(){if(new URLSearchParams(location.search).has('reset')){renderAuth('reset');return;}try{const result=await api('/me');state.user=result.user;await refresh();}catch{renderAuth();}}
function pendingRequest(appointment){
  return ['Pending','Approved'].includes(appointment.status)&&(
    !!appointment.request||state.data.reschedules.some(r=>r.appointment_id===appointment.id&&r.status==='Pending')
  );
}
function dentistsPage(){
  return heading('Meet your dental care team.','Choose the dentist you feel most comfortable with.')+
    `<div class="dentist-grid">${state.data.dentists.map(d=>`<section class="dentist-card">
      <div class="dentist-card-top"><span class="dentist-avatar">${esc(initials(d.name.replace('Dr. ','')))}</span><span class="availability ${d.available?'available':'unavailable'}"><i></i>${d.available?'Available':'Not available'}</span></div>
      <div class="eyebrow">Your care team</div><h2>${esc(d.name)}</h2><div class="dentist-specialty">${esc(d.specialty)}</div><p>${esc(d.bio)}</p>
      <div class="dentist-hours">${icon('calendar')}Mon–Sat · 9:00 AM–5:00 PM</div>
      ${isAdmin()?`<button class="button" data-availability="${d.id}" data-available="${!d.available}">${d.available?'Mark not available':'Mark available'}</button>`:`<button class="button primary" data-dentist="${d.id}" ${!d.available?'disabled':''}>${icon('calendar')}${d.available?'Book with this dentist':'Currently unavailable'}</button>`}
    </section>`).join('')}</div><p class="form-hint section-gap">These are sample dentist profiles for local testing. Availability reflects the clinic’s current booking status; individual appointment times are checked when booking.</p>`;
}
function accountsPage(){
  if(!isAdmin())return heading('Account management','Administrator access is required.');
  return heading('Account management','Give trusted registered accounts access to the clinic workspace.')+
    `<section class="panel"><div class="panel-heading"><div><h2 class="panel-title">Website accounts</h2><div class="panel-subtitle">${state.data.accounts.filter(a=>a.role==='admin').length} administrators · ${state.data.accounts.length} registered accounts</div></div></div><div class="info-box m-3">Administrators can manage clinic appointments, view patient information, and grant admin access to other accounts. The person must have a registered account before you can promote them.</div><div class="table-toolbar">${searchInput('Search name, username, or email…')}</div><div id="accounts-table">${accountsTable()}</div></section>`;
}
function accountsTable(){
  const accounts=state.data.accounts.filter(a=>`${a.name} ${a.username||''} ${a.email}`.toLowerCase().includes(state.search.toLowerCase()));
  return `<div class="table-scroll"><table aria-label="Website accounts"><thead><tr><th>Account</th><th>Role</th><th>Admin access granted by</th><th>Action</th></tr></thead><tbody>${accounts.map(a=>`<tr><td>${person(a.name,a.username||a.email,a.id)}</td><td><span class="badge-status ${a.role==='admin'?'approved':'completed'}">${a.role==='admin'?'Administrator':'Patient'}</span>${a.id===state.user.id?'<small class="dentist-caption">Your account</small>':''}</td><td>${a.promoted_by?`${esc(a.promoted_by)}<small class="dentist-caption">${esc(a.promoted_at)} UTC</small>`:a.role==='admin'?'Initial administrator':'—'}</td><td>${a.role==='admin'?'<span class="form-hint">Admin access enabled</span>':`<button class="button" data-promote="${a.id}">${icon('shield')}Make admin</button>`}</td></tr>`).join('')}</tbody></table>${accounts.length?'':'<div class="empty">No accounts match your search.</div>'}</div>`;
}
function promoteAccountModal(id){
  if(!isAdmin())return;
  const account=state.data.accounts.find(a=>a.id===id);
  if(!account||account.role==='admin')return;
  showModal('Grant administrator access?',`${person(account.name,account.email,account.id)}<div class="info-box mt-4">This account will have the same administrative permissions as you, including patient records, appointment management, and the ability to add more admins.</div><p class="form-hint mt-3">Their current sessions will end. They can sign in again with the same email and password to use the staff workspace.</p><div class="form-error" id="promote-error"></div>`,`<button class="button" data-close>Cancel</button><button class="button primary" id="confirm-promotion">${icon('shield')}Grant admin access</button>`);
  $('#confirm-promotion').onclick=async event=>{
    const button=event.currentTarget;button.disabled=true;
    try{const result=await api('/accounts/'+id+'/promote','POST',{});closeModal();await refresh();toast(result.message);}
    catch(error){if($('#promote-error'))$('#promote-error').textContent=error.message;else toast(error.message);button.disabled=false;}
  };
}
function serviceHistoryPage(){
  const completed=state.data.appointments.filter(a=>a.status==='Completed');
  return heading('Service history','A history log of the dental services you have received.')+
    `<section class="panel"><div class="panel-heading"><div><h2 class="panel-title">Completed dental services</h2><div class="panel-subtitle">Your completed visits, with the treatment date and attending dentist.</div></div><span class="count-label">${completed.length} completed visits</span></div>
    <div class="table-toolbar" style="padding-top:20px">${searchInput('Search service, dentist, or date…')}<select class="filter-select" id="service-filter" aria-label="Filter by service">${serviceOptions()}</select></div><div id="appointment-table">${serviceHistoryTable()}</div></section>`;
}
function serviceHistoryTable(){
  const visits=state.data.appointments.filter(a=>a.status==='Completed'&&(state.filter==='All services'||a.service===state.filter)&&`${a.service} ${a.dentist_name} ${a.date} ${dateFormat(a.date)}`.toLowerCase().includes(state.search.toLowerCase())).sort((a,b)=>b.date.localeCompare(a.date)||b.time.localeCompare(a.time));
  const limit=9,pages=Math.max(1,Math.ceil(visits.length/limit));state.page=Math.min(state.page,pages);
  const records=visits.slice((state.page-1)*limit,state.page*limit);
  return `<div class="table-scroll"><table aria-label="Completed dental service history"><thead><tr><th>Dental service received</th><th>Date of visit</th><th>Time</th><th>Dentist</th><th>Status</th><th aria-label="Actions"></th></tr></thead><tbody>${records.map(a=>`<tr><td><strong class="service-text">${esc(a.service)}</strong><small class="dentist-caption">#PD-${String(a.id).padStart(4,'0')}</small></td><td>${dateFormat(a.date)}</td><td>${timeFormat(a.time)}</td><td>${esc(a.dentist_name)}</td><td>${statusBadge(a.status)}</td><td><button class="text-link" data-detail="${a.id}">View record ${icon('arrow')}</button></td></tr>`).join('')}</tbody></table>${!records.length?`<div class="empty">${icon('file')}${state.data.appointments.some(a=>a.status==='Completed')?'No completed services match your search.':'Your completed dental services will appear here after your visit.'}</div>`:''}</div>
    <div class="table-footer"><span>${visits.length?`Showing ${(state.page-1)*limit+1}–${Math.min(state.page*limit,visits.length)} of ${visits.length} completed visits`:'No completed services to show'}</span><div class="pager"><button class="button" data-page="${state.page-1}" ${state.page<=1?'disabled':''} aria-label="Previous page">${icon('left')}</button><span class="page-num">${state.page}</span><button class="button" data-page="${state.page+1}" ${state.page>=pages?'disabled':''} aria-label="Next page">${icon('chevron')}</button></div></div>`;
}
function patientFollowupsPage(){
  return heading('Follow up appointments','View visits recommended by your administrator or request a schedule change.')+followupPlan();
}
// Refresh shared clinic changes without interrupting forms or open dialogs.
async function syncUpdates(){
  if(!state.user||state.accountMenu||document.hidden||document.querySelector('.app-modal')||document.activeElement?.matches('input,select,textarea'))return;
  try{const data=await api('/data');if(JSON.stringify(data)!==JSON.stringify(state.data)){state.data=data;state.user=data.user;render();}}catch{}
}
window.addEventListener('focus',syncUpdates);
setInterval(syncUpdates,30000);
init();
